B.aoj=new A.I(415,B.WY)
B.a31=s(["Saying \u201cstop dictation\u201d now turns off dictation, same as \u201cend dictation\u201d (also: \u201cstop note\u201d, \u201cstop dictating\u201d)."],t.s)
B.ao3=new A.I(414,B.a31)
